// Verifies that the call really comes from LendLoop before anything else runs.
// The shared secret is read from the environment, never stored in this workflow.
const crypto = require('crypto');

const MAX_AGE_MS = 5 * 60 * 1000;

const item = $input.first();
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
const headers = item.json.headers ?? {};
const timestamp = String(headers['x-lendloop-timestamp'] ?? '');
const signature = String(headers['x-lendloop-signature'] ?? '');

function reject(reason) {
  // The reason stays in the execution log; the caller only gets a 401.
  return [{ json: { valid: false, reason } }];
}

if (!secret) {
  throw new Error('LENDLOOP_WEBHOOK_SECRET is not set on this n8n instance');
}
if (!/^\d+$/.test(timestamp) || !/^[0-9a-f]{64}$/.test(signature)) {
  return reject('missing or malformed signature headers');
}
if (Math.abs(Date.now() - Number(timestamp)) > MAX_AGE_MS) {
  return reject('timestamp outside the 5 minute window');
}

// Sign the exact bytes that were received, not a re-serialised copy.
const rawBody = await this.helpers.getBinaryDataBuffer(0, 'data');
const expected = crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.`)
  .update(rawBody)
  .digest();
const received = Buffer.from(signature, 'hex');

// Constant-time comparison: the time taken reveals nothing about the match.
if (received.length !== expected.length || !crypto.timingSafeEqual(received, expected)) {
  return reject('signature mismatch');
}

return [{ json: { valid: true, payload: JSON.parse(rawBody.toString('utf8')) } }];

// Mock notification: builds the message that would be emailed and leaves it
// in the execution data. Swap this node for an email node to send it for real.
const { eventId, loanId, status, recipientEmail, toolName } = $input.first().json.payload;

const subjects = {
  pending: `New request to borrow your ${toolName}`,
  approved: `Your request for the ${toolName} was approved`,
  declined: `Your request for the ${toolName} was declined`,
  returned: `The ${toolName} was marked as returned`,
};

return [{
  json: {
    eventId,
    loanId,
    to: recipientEmail,
    subject: subjects[status] ?? `Update about the ${toolName}`,
    delivered: 'mock',
  },
}];
